"""生成离线可打开的组件预览目录；不把配置编辑冒充已渲染视频更新。"""
from pathlib import Path
import json
P=Path(__file__).resolve().parent
catalog=json.loads((P/'catalog.json').read_text());variants={r['id']:{v:json.loads((P/'variants'/(r['id']+'-'+v+'.json')).read_text()) for v in ['default','long']} for r in catalog['components']}
validation=json.loads((P/'validation.json').read_text()) if (P/'validation.json').exists() else {}
hashes={x['component']+'-'+x['variant']:x['sha256'] for x in validation.get('renders',[])}
DATA=json.dumps({'catalog':catalog['components'],'variants':variants,'hashes':hashes},ensure_ascii=False).replace('</','<\\/')
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>fred mg 1 · 23个独立组件</title><style>*{box-sizing:border-box}body{margin:0;background:#17171d;color:#f4f0f9;font:17px/1.6 system-ui}main{max-width:1320px;margin:auto;padding:32px 24px}h1{font-size:34px;margin:12px 0}h2{font-size:23px}p{color:#d1c9dc}a{color:#dfc6ff}button,select,textarea{font:inherit;color:inherit;background:#292331;border:1px solid #a895bd;border-radius:8px;padding:11px 14px}button{cursor:pointer;margin:6px 6px 6px 0}button.active{background:#c6a4fa;color:#17171d}label{display:block;margin:14px 0 6px}.grid{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(320px,1fr);gap:24px}video{display:block;width:100%;aspect-ratio:16/9;background:#08070a;border:1px solid #877c98;border-radius:10px}textarea{width:100%;height:370px;font:14px/1.55 ui-monospace,monospace}select{width:100%}.panel{padding:20px;border:1px solid #796b8d;border-radius:12px}.hint{font-size:15px}#status{min-height:30px;color:#dfc6ff}code{word-break:break-all}#list{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}#list button{text-align:left}#list img{width:100%;aspect-ratio:16/9;object-fit:contain;display:block;background:#222}@media(max-width:850px){.grid{grid-template-columns:1fr}#list{grid-template-columns:repeat(2,minmax(0,1fr))}}</style></head><body><main><p>FRED MG 1 · HYPERFRAMES</p><h1>23个动作，分别预览和复用</h1><p>每个组件都有自己的模板、参数、媒体和时间线。选择组件，查看默认版或加长参数测试，再导出配置。</p><p><a href="README.md">使用说明</a> · <a href="validation.json">验证记录</a> · <a href="../README.md">风格首页</a></p><div class="grid"><section><h2 id="name"></h2><video id="player" controls muted playsinline preload="metadata"></video><button id="play-all">按1倍速依次播放23个默认组件</button><button id="stop-all">停止连播</button><p id="play-status" class="hint">尚未开始连播。</p><button data-variant="default">默认版</button><button data-variant="long">加长参数测试</button><p id="info"></p><p class="hint">播放器显示已渲染的样例。修改配置后，需重新构建和渲染，视频才会更新。</p><p class="hint">从仓库根目录构建：</p><code>python3 fred-mg-1/components/build.py --config config.json --output .build/my-clip</code></section><section class="panel"><label for="component">选择组件</label><select id="component"></select><label for="config">独立配置</label><textarea id="config" spellcheck="false"></textarea><button id="apply">检查配置格式</button><button id="export">导出配置</button><p id="status">配置已载入。</p><p class="hint" id="fields"></p></section></div><h2>全部组件</h2><div id="list"></div><p class="hint">默认时长包含完整原动作；加长主要增加展示时间，章节退场跟随新总长。视频保持原速。带变化节点的进度条和视频墙绑定时长不能用普通动作时长覆盖。</p><p class="hint">本页为通用素材组件测试，不替代原素材复现。技术检查、实际图复核和用户认可分别记录。</p></main><script>const D=__DATA__,select=document.querySelector('#component'),box=document.querySelector('#config'),player=document.querySelector('#player'),status=document.querySelector('#status');let variant='default',playingAll=false,playIndex=0;const playStatus=document.querySelector('#play-status');for(const r of D.catalog){const o=document.createElement('option');o.value=r.id;o.textContent=r.id+' · '+r.name;select.append(o);const b=document.createElement('button'),im=document.createElement('img'),t=document.createElement('span');im.src='previews/covers/'+r.id+'.png';t.textContent=r.id+' · '+r.name;b.append(im,t);b.onclick=()=>{select.value=r.id;show();player.scrollIntoView({block:'center'});};document.querySelector('#list').append(b);}function show(){const r=D.catalog.find(x=>x.id===select.value),s=D.variants[r.id][variant];box.value=JSON.stringify(s,null,2);player.src='previews/'+variant+'/'+r.id+'.mp4?v='+(D.hashes[r.id+'-'+variant]||'');player.poster='previews/covers/'+r.id+'.png';document.querySelector('#name').textContent=r.name+' · '+(variant==='default'?'默认版':'加长参数测试');document.querySelector('#info').textContent=s.duration.toFixed(3)+'秒 · 1920×1080 · 30fps';document.querySelector('#fields').textContent='可改文字：'+r.fields.map(x=>x.key).join('、')+'；数据：'+Object.keys(r.data_fields).join('、')+'；媒体插槽：'+Object.keys(r.media).length+'个。完整字段见catalog.json。';status.textContent='配置已载入。实际参数和媒体校验由构建命令执行。';for(const b of document.querySelectorAll('[data-variant]'))b.classList.toggle('active',b.dataset.variant===variant);}select.onchange=()=>{playingAll=false;show();};for(const b of document.querySelectorAll('[data-variant]'))b.onclick=()=>{playingAll=false;variant=b.dataset.variant;show();};function read(){const s=JSON.parse(box.value),r=D.catalog.find(x=>x.id===s.component);if(!r)throw Error('请选择已登记的组件ID。');if(typeof s.duration!=='number'||s.duration<r.duration-0.00001||s.duration>30||Math.abs(s.duration*30-Math.round(s.duration*30))>0.00001)throw Error('时长须在'+r.duration.toFixed(3)+'至30秒，并按1/30秒对齐。');return s;}document.querySelector('#apply').onclick=()=>{try{read();status.textContent='配置格式可读取。导出后运行构建命令，完成参数和素材校验。';}catch(e){status.textContent=e instanceof SyntaxError?'JSON格式有误，请检查引号、逗号和括号。':e.message;}};document.querySelector('#export').onclick=()=>{try{const s=read(),u=URL.createObjectURL(new Blob([JSON.stringify(s,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='config.json';a.click();URL.revokeObjectURL(u);status.textContent='已导出配置。重新构建和渲染后查看结果。';}catch(e){status.textContent=e.message;}};document.querySelector('#play-all').onclick=()=>{playingAll=true;playIndex=0;variant='default';select.value=D.catalog[0].id;show();player.defaultPlaybackRate=1;player.playbackRate=1;player.play();player.scrollIntoView({block:'center'});};document.querySelector('#stop-all').onclick=()=>{playingAll=false;player.pause();playStatus.textContent='连播已停止。';};player.ontimeupdate=()=>{if(playingAll)playStatus.textContent='正在播放 '+(playIndex+1)+'/23 · '+select.value+' · '+player.currentTime.toFixed(2)+'秒 · '+player.playbackRate+'倍速';};player.onended=()=>{if(!playingAll)return;playIndex++;if(playIndex>=D.catalog.length){playingAll=false;playStatus.textContent='已完成23个默认组件播放。最后速率：'+player.playbackRate+'倍速。';return;}select.value=D.catalog[playIndex].id;show();player.defaultPlaybackRate=1;player.playbackRate=1;player.play();};show();</script></body></html>'''
(P/'preview.html').write_text(html.replace('__DATA__',DATA));print('preview.html ready')
